import Foundation
struct HostFailure:Error{let message:String}
@main @MainActor struct NativeTasksHostProtocolTests {
 static var count=0,failures=0
 static let client="12345678-1234-4123-8123-123456789abc"
 static let frame=NativeTaskRectangle(x:0,y:0,width:1000,height:700)
 static func check(_ value:@autoclosure()throws->Bool,_ message:String)throws{if try !value(){throw HostFailure(message:message)}}
 static func reject(_ body:()throws->Void)throws{do{try body()}catch is HostFailure{throw HostFailure(message:"assert inside rejection")}catch{return};throw HostFailure(message:"expected refusal")}
 static func run(_ name:String,_ body:()throws->Void){do{try body();count+=1;print("PASS "+name)}catch{failures+=1;print("FAIL "+name+": "+((error as? HostFailure)?.message ?? String(describing:type(of:error))))}}
 static func context()->NativeTaskHostContext{.init(owner:.init(windowID:UUID(),documentID:UUID(),contextGeneration:0),paperID:"")}
 static func metrics(_ change:[String:Any]=[:])throws->NativeTaskDOMObservation{var raw:[String:Any]=["clientID":client,"tasksVisible":true,"blocked":false,"width":1000,"height":700,"main":["x":200,"y":0,"width":800,"height":700],"toolbar":["x":200,"y":0,"width":800,"height":62],"sidebarVisible":true,"sidebar":["x":0,"y":0,"width":200,"height":700],"tasks":["x":200,"y":62,"width":800,"height":638]];raw.merge(change){_,new in new};return try .init(raw)}
 static func bootstrap(_ c:NativeTaskHostCoordinator)throws->String{try c.bootstrap(client:client,paperID:c.context.paperID,observedClient:client,current:c.context)["nonce"] as! String}
 static func request(_ nonce:String,_ seq:Int64=1,tasks:Bool=true,change:[String:Any]=[:])throws->NativeTaskPresentRequest{var raw:[String:Any]=["nonce":nonce,"clientID":client,"paperID":"","sequence":seq,"tasks":tasks,"focus":false];raw.merge(change){_,new in new};return try .init(raw)}
 static func ready(_ c:NativeTaskHostCoordinator,_ n:String,seq:Int64=1)throws->NativeTaskHostTicket{let t=try c.reserve(request(n,seq),current:c.context);_ = try c.finish(t,current:c.context,observation:metrics(),nativeFrame:frame,pageZoom:1);return t}
 static func main(){
  run("only actual main view top-frame fixed URL"){let u=URL(string:"paperapp://app/index.html")!;try check(NativeTaskHostCoordinator.sourceAllowed(isMainView:true,isMainFrame:true,url:u),"valid source");for (main,top,url)in [(false,true,u),(true,false,u),(true,true,URL(string:"paperapp://app/settings.html")!),(true,true,URL(string:"paperapp://app/index.html?old")!),(true,true,URL(string:"https://app/index.html")!)]{try check(!NativeTaskHostCoordinator.sourceAllowed(isMainView:main,isMainFrame:top,url:url),"foreign source")}}
  run("strict payload no arbitrary fields types") {let n=UUID().uuidString.lowercased();for change:[String:Any] in [["sequence":true],["sequence":1.5],["sequence":0],["tasks":1],["focus":"yes"],["command":"model.run"]]{try reject{_ = try request(n,change:change)}}}
  run("bootstrap native nonce only same observed document") {let c=NativeTaskHostCoordinator(context:context());try reject{_ = try c.bootstrap(client:client,paperID:"",observedClient:UUID().uuidString.lowercased(),current:c.context)};try check(NativeTaskHostCoordinator.validID(bootstrap(c)),"nonce not generated")}
  run("bootstrap wrong paper or changed owner refuses") {let c=NativeTaskHostCoordinator(context:context());try reject{_ = try c.bootstrap(client:client,paperID:"other",observedClient:client,current:c.context)};try reject{_ = try c.bootstrap(client:client,paperID:"",observedClient:client,current:context())}}
  run("repeat bootstrap retains high water") {let c=NativeTaskHostCoordinator(context:context());let n=try bootstrap(c);_ = try ready(c,n,seq:8);let same=try c.bootstrap(client:client,paperID:"",observedClient:client,current:c.context);try check(same["nonce"] as? String==n && same["highestSequence"] as? Int64==8,"reset replay guard");try reject{_ = try c.reserve(request(n,8),current:c.context)}}
  run("same URL new client cannot steal existing document") {let c=NativeTaskHostCoordinator(context:context());_ = try bootstrap(c);let next=UUID().uuidString.lowercased();try reject{_ = try c.bootstrap(client:next,paperID:"",observedClient:next,current:c.context)}}
  run("wrong nonce client or paper refuses") {let c=NativeTaskHostCoordinator(context:context());let n=try bootstrap(c);for change:[String:Any] in [["nonce":UUID().uuidString.lowercased()],["clientID":UUID().uuidString.lowercased()],["paperID":"other"]]{try reject{_ = try c.reserve(request(n,change:change),current:c.context)}}}
  run("native geometry excludes sidebar and toolbar converted") {let c=NativeTaskHostCoordinator(context:context()),n=try bootstrap(c);let t=try c.reserve(request(n),current:c.context);let v=try c.finish(t,current:c.context,observation:metrics(),nativeFrame:frame,pageZoom:1);try check(v?.layout.rectangle == .init(x:200,y:0,width:800,height:638),"wrong CSS to native");_ = try c.invocation()}
  run("out of band sidebar or toolbar measurement refuses") {for rect:[String:Any] in [["x":0,"y":62,"width":1000,"height":638],["x":200,"y":0,"width":800,"height":700],["x":200,"y":62,"width":801,"height":638]]{try reject{_ = try metrics(["tasks":rect]).geometry(nativeFrame:frame,pageZoom:1)}}}
  run("nonfinite bool malformed viewport refused") {for change:[String:Any] in [["width":true],["width":Double.nan],["height":-1]]{try reject{_ = try metrics(change).geometry(nativeFrame:frame,pageZoom:1)}};try reject{_ = try metrics().geometry(nativeFrame:frame,pageZoom:Double.infinity)}}
  run("blocked or hidden DOM cannot show native") {for change:[String:Any] in [["blocked":true],["tasksVisible":false]]{let c=NativeTaskHostCoordinator(context:context()),n=try bootstrap(c),t=try c.reserve(request(n),current:c.context);try reject{_ = try c.finish(t,current:c.context,observation:metrics(change),nativeFrame:frame,pageZoom:1)};try reject{_ = try c.invocation()}}}
  run("late old measure cannot retire new accepted frame") {let c=NativeTaskHostCoordinator(context:context()),n=try bootstrap(c),old=try c.reserve(request(n),current:c.context);_ = try ready(c,n,seq:2);let now=try c.invocation();try reject{_ = try c.finish(old,current:c.context,observation:metrics(),nativeFrame:frame,pageZoom:1)};try check(!c.isLatest(old,current:c.context),"old flagged latest");try c.requireCurrent(now,current:c.context)}
  run("pending new request forbids old callback") {let c=NativeTaskHostCoordinator(context:context()),n=try bootstrap(c);_ = try ready(c,n);let old=try c.invocation();_ = try c.reserve(request(n,2),current:c.context);try reject{try c.requireCurrent(old,current:c.context)}}
  run("leaving retires actual invocation") {let c=NativeTaskHostCoordinator(context:context()),n=try bootstrap(c);_ = try ready(c,n);let token=try c.invocation(),leave=try c.reserve(request(n,2,tasks:false),current:c.context);try check(try c.finish(leave,current:c.context,observation:nil,nativeFrame:frame,pageZoom:1)==nil,"leave showed content");try reject{try c.requireCurrent(token,current:c.context)}}
  run("context and restore epoch change invalidate old nonce") {let c=NativeTaskHostCoordinator(context:context()),n=try bootstrap(c);_ = try ready(c,n);let old=try c.invocation();var next=c.context;next = .init(owner:.init(windowID:next.owner.windowID,documentID:next.owner.documentID,contextGeneration:1),paperID:"");c.replaceContext(next);try reject{try c.requireCurrent(old,current:c.context)};try reject{_ = try c.reserve(request(n,2),current:c.context)};let fresh=try bootstrap(c);try check(n != fresh,"reused old nonce")}
  run("same context does not reset accepted state") {let c=NativeTaskHostCoordinator(context:context()),n=try bootstrap(c);_ = try ready(c,n,seq:3);let token=try c.invocation();c.replaceContext(c.context);try c.requireCurrent(token,current:c.context);try reject{_ = try c.reserve(request(n,3),current:c.context)}}
  run("changed document measurement refuses") {let c=NativeTaskHostCoordinator(context:context()),n=try bootstrap(c),t=try c.reserve(request(n),current:c.context);try reject{_ = try c.finish(t,current:c.context,observation:metrics(["clientID":UUID().uuidString.lowercased()]),nativeFrame:frame,pageZoom:1)};try reject{_ = try c.invocation()}}
  print("RESULT \(count) passed / \(failures) failed");exit(failures==0 ? 0:1)
 }
}
